#!/usr/bin/env python3
"""
Adds the Reel Ideas tab to the HAGGERTY marketing dashboard.

    python3 apply-reels-patch.py index.html

Six anchored insertions. Every anchor must appear exactly once or the script
changes nothing and tells you which one was wrong. A .bak copy is written
first. Running it twice is safe: it detects the patch and stops.

    python3 apply-reels-patch.py --show     print the code it will insert
"""
import sys, base64, shutil, pathlib

CSS   = base64.b64decode("").decode()
JS    = base64.b64decode("").decode()
STATE = base64.b64decode("").decode()

MARKER = "/* ================= reel ideas ================= */"

# (label, anchor, payload, where)  where = "before" | "after" | "replace"
EDITS = [
    ("1. CSS block",
     "  /* ---------- states ---------- */",
     CSS + "\n\n",
     "before"),

    ("2. PAGES entry",
     """  ['iyanna',"Iyanna's Day"], ['leads','Leads']""",
     """  ['iyanna',"Iyanna's Day"], ['reels','Reel Ideas'], ['leads','Leads']""",
     "replace"),

    ("3. state block",
     "  reqShowDone:false,",
     "\n" + STATE,
     "after"),

    ("4a. ensure() loader",
     "  if(page === 'myday' && !S.loaded.requests) await loadRequests();",
     "\n  if(page==='reels' && !S.loaded.reels) await loadReels();",
     "after"),

    ("4b. render() dispatch",
     "  if(S.page==='approvals') inner = pageApprovals();",
     "\n  if(S.page==='reels')    inner = pageReels();",
     "after"),

    ("4c. wirePage() call",
     "  wireApprovals();",
     "\n  wireReels();",
     "after"),

    ("5. page code",
     "/* ================= boot ================= */",
     JS + "\n\n",
     "before"),
]


def main():
    if "--show" in sys.argv:
        print("=== CSS ===\n" + CSS + "\n\n=== STATE ===\n" + STATE
              + "\n\n=== JS ===\n" + JS)
        return 0

    args = [a for a in sys.argv[1:] if not a.startswith("-")]
    path = pathlib.Path(args[0] if args else "index.html")
    if not path.is_file():
        print("Cannot find " + str(path)); return 1

    src = path.read_text(encoding="utf-8")

    if MARKER in src:
        print("Already patched. Nothing to do."); return 0

    # Verify every anchor before touching anything.
    problems = []
    for label, anchor, _, _ in EDITS:
        n = src.count(anchor)
        if n != 1:
            problems.append("  " + label + ": anchor found " + str(n)
                            + " times, expected 1\n    " + anchor.strip()[:70])
    if problems:
        print("Stopping, file not changed. Anchor problems:\n"
              + "\n".join(problems))
        return 1

    out = src
    for label, anchor, payload, where in EDITS:
        if where == "before":
            out = out.replace(anchor, payload + anchor, 1)
        elif where == "after":
            out = out.replace(anchor, anchor + payload, 1)
        else:
            out = out.replace(anchor, payload, 1)

    backup = path.with_suffix(path.suffix + ".bak")
    shutil.copyfile(path, backup)
    path.write_text(out, encoding="utf-8")

    print("Patched " + str(path))
    print("  backup     " + str(backup))
    print("  added      " + str(len(out) - len(src)) + " bytes, "
          + str(out.count(chr(10)) - src.count(chr(10))) + " lines")
    for label, _, _, _ in EDITS:
        print("  applied    " + label)
    print("\nNow run:  git diff --stat   then   git diff")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
